import {advancedDecisions,knowledgeDecisions} from './advanced-decisions.js?v=20261015-llm3';
const round=x=>Number(x.toFixed(2));
const money=x=>round(x).toLocaleString('ko-KR');

// 세트마다 동일 자료로 정답과 오개념 보기를 계산합니다. 정답 위치는 question()에서 섞습니다.
export function buildAdvancedBank(exam){
 const bank=[],mode=exam.mode;
 const add=(topic,prompt,answers,explanation,refs,dimension)=>{
  const [correct,...wrong]=answers;
  if(new Set(answers.map(a=>a[0])).size!==4)throw new Error(`보기 충돌: ${mode}/${topic}`);
  const q=question(topic,'',prompt,correct[0],wrong.map(a=>a[0]),explanation,'자료의 모집단·기간·제외 조건을 먼저 고정한 뒤 각 대안에 같은 기준을 적용하세요.');
  q.id=`${mode}:advanced:${topic}`;q.difficulty='상';q.skill='복합 자료 추론';
  q.evidence=refs.map(document=>({document,locator:'해당 기록 및 적용 조건'}));
  q.optionReasons=q.options.map(o=>answers.find(a=>a[0]===o)[1]);
  if(mode==='ax')q.dimension=dimension||'AX 문제해결';
  bank.push(q);return q;
 };
 const numeric=(topic,prompt,value,unit,distractors,explanation,refs,dimension)=>{
  const fmt=n=>`${money(n)}${unit}`;
  const answer=fmt(value),used=new Set([answer]);
  const wrong=[];
  for(const [v,why] of distractors){const text=fmt(v);if(!used.has(text)){used.add(text);wrong.push([text,why]);}}
  if(wrong.length<3)throw new Error(`오답 부족: ${mode}/${topic}`);
  add(topic,prompt,[[answer,explanation],...wrong.slice(0,3)],explanation,refs,dimension);
 };
 const block=(id,headers,rows,rules)=>{
  const name=`심화_${id}_원장`,policy=`심화_${id}_판정조건`;
  exam.documents.push({name,type:'table',headers,rows,note:'후속 심화 검토의 별도 모집단·기간입니다. 기존 기초 집계와 합산하지 않습니다. 금액은 명시 단위, 계산은 최종 단계에서 소수 둘째 자리까지 반올림합니다.'},{name:policy,type:'memo',paragraphs:rules});
  return [name,policy];
 };
 const k=pick([1,2,3,4]);
 if(mode!=='knowledge')quantitative[mode]({numeric,add,block,k});
 if(mode==='ax')bank.forEach((q,i)=>q.dimension=(i<4||i===8||i===9)?'기본 직무역량':'AX 문제해결');
 const cases=mode==='knowledge'?knowledgeDecisions:advancedDecisions[mode];
 cases.forEach((c,i)=>{
  const [topic,facts,conditions,prompt,answers,explanation]=c;
  let refs=[];
  if(mode!=='knowledge'){
   refs=block(`판단${i+1}`,['기록','관측 사실'],facts.map((f,j)=>[`J${i+1}-${j+1}`,f]),conditions);
  }
  const q=add(topic,prompt,answers,explanation,refs,mode==='ax'?(i%2?'AX 문제해결':'기본 직무역량'):undefined);
  q.skill='조건부 의사결정';
  if(mode==='knowledge')q.scenario=[...facts,...conditions].join('\n');
 });
 return bank;
}
